{
  "findings": [
    {
      "finding_id": "DD-1",
      "drift_kind": "name",
      "explanation": "The templates guide documents an autoescape callback that returns `False` for `None`, but `select_autoescape` returns `default_for_string`, whose default is `True`, for a `None` template name.",
      "doc_citation": {
        "path": "jinja/docs/templates.rst",
        "start_line": 249,
        "end_line": 251,
        "quote": "        if template_name is None:\n            return False\n        if template_name.endswith(('.html', '.htm', '.xml'))"
      },
      "code_citation": {
        "path": "jinja/src/jinja2/utils.py",
        "start_line": 624,
        "end_line": 626,
        "quote": "def autoescape(template_name: str | None) -> bool:\n        if template_name is None:\n            return default_for_string"
      },
      "proposed_fix": "Change the documented example to return `default_for_string` when `template_name is None`, matching `select_autoescape`."
    },
    {
      "finding_id": "DD-2",
      "drift_kind": "name",
      "explanation": "The API docs load a template with `Environment.get_tmpl`, but the public method is `Environment.get_template`.",
      "doc_citation": {
        "path": "jinja/docs/api.rst",
        "start_line": 55,
        "end_line": 55,
        "quote": "template = env.get_tmpl(\"mytemplate.html\")"
      },
